 n,lab,stats,cent=cv2.connectedComponentsWithStats(m)
 print('\\n',name)
 for j in np.argsort(stats[1:,4])[::-1][:20]+1:
  x,y,w,h,a=stats[j];
  if a>4: print(a,(x,y,w,h),np.round(cent[j],1))
